/* --- diagrams --- */
function mbPath(a, h, x0, y0, w, ht) {
  var pts = [];
  for (var i = 0; i <= 80; i++) {
    var u = i / 80 * 3.2, f = u * u * Math.exp(-u * u / (a * a)) / (a * a * a);
    pts.push((x0 + u / 3.2 * w).toFixed(1) + ',' + (y0 - f * h * ht).toFixed(1));
  }
  return 'M' + pts.join(' L');
}
